// Read every input item and collect all vehicles across them.
const vehicles = [];
for (const item of $input.all()) {
  const resp = item.json || {};
  if (Array.isArray(resp.data)) {
    for (const v of resp.data) vehicles.push(v);
  }
}

// One consistent snapshot timestamp for the whole run.
const now = $now.toFormat('yyyy-MM-dd HH:mm:ss');

function techName(v, field) {
  const obj = v ? v[field] : null;
  if (obj && typeof obj === 'object') {
    return obj.technicalName != null ? obj.technicalName : '';
  }
  return '';
}

return vehicles.map((v) => {
  const price = v.price || {};
  const address = v.address || {};
  return {
    json: {
      'VIN': v.VIN != null ? v.VIN : '',
      'Model Year': v.modelYear != null ? v.modelYear : '',
      'Availability': v.availability != null ? v.availability : '',
      'In Transit': v.isInTransit != null ? v.isInTransit : '',
      'At Studio': v.isAtStudio != null ? v.isAtStudio : '',
      'At Hub': v.isAtHub != null ? v.isAtHub : '',
      'Title Status': v.titleStatus != null ? v.titleStatus : '',
      'Category': v.category != null ? v.category : '',
      'Sales Status': v.salesStatus != null ? v.salesStatus : '',
      'Model': techName(v, 'model'),
      'Color': techName(v, 'color'),
      'Interior': techName(v, 'interior'),
      'Wheels': techName(v, 'wheels'),
      'Roof': techName(v, 'roof'),
      'Look/Trim': techName(v, 'look'),
      'Seating': techName(v, 'seating'),
      'Packages': techName(v, 'packages'),
      'Driver Assistance': techName(v, 'driverAssistance'),
      'Sound System': techName(v, 'soundSystem'),
      'Price': price.value != null ? price.value : '',
      'Greater Area': address.greaterArea != null ? address.greaterArea : '',
      'State': address.state != null ? address.state : '',
      'Image URL': v.imageURL != null ? v.imageURL : '',
      'Snapshot Time': now,
    },
  };
});

// Full History rows come in as this node's input; current snapshot comes from Flatten.
const historyRows = $input.all().map(i => i.json).filter(r => r && r.VIN);
const currentRows = $('Flatten Vehicles').all().map(i => i.json).filter(r => r && r.VIN);

const DAY = 24 * 60 * 60 * 1000;

// Tolerant timestamp parser (Google Sheets may re-render with non-padded hours).
function toEpoch(ts) {
  const s = String(ts == null ? '' : ts).trim();
  const m = s.match(/(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?/);
  if (m) return new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +(m[6] || 0)).getTime();
  const d = new Date(s).getTime();
  return isNaN(d) ? null : d;
}
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function num(x) { const n = Number(String(x == null ? '' : x).replace(/[^0-9.\-]/g, '')); return isFinite(n) ? n : null; }
function sum(a) { let t = 0; for (const x of a) t += x; return t; }
function round(n, d) { const f = Math.pow(10, d == null ? 2 : d); return Math.round(n * f) / f; }
function pct(n, d) { return d ? round((n / d) * 100, 1) : 0; }
function median(arr) { if (!arr.length) return 0; const a = arr.slice().sort((x, y) => x - y); const mid = Math.floor(a.length / 2); return a.length % 2 ? a[mid] : (a[mid - 1] + a[mid]) / 2; }
function money(n) { return (n === '' || n == null) ? '' : '$' + Number(n).toLocaleString('en-US'); }
function isTrue(x) { return x === true || String(x).toLowerCase() === 'true'; }
function trimOf(model) { const m = String(model || ''); if (/grand touring/i.test(m)) return 'Grand Touring'; if (/touring/i.test(m)) return 'Touring'; if (/pure/i.test(m)) return 'Pure'; return m || 'Other'; }

const currentSnapshotTime = currentRows.length ? String(currentRows[0]['Snapshot Time'] || '') : '';
const currentEpoch = toEpoch(currentSnapshotTime);

// Lifecycle maps keyed by epoch so timestamp formatting differences don't matter.
const byEpoch = {};        // epoch -> { vin: true }
const priceByEpoch = {};   // epoch -> { vin: price }
const vinFirst = {};       // vin -> earliest epoch
const vinLast = {};        // vin -> latest epoch
const vinLastRow = {};     // vin -> row at latest epoch

function observe(vin, epoch, row) {
  if (!vin || epoch == null) return;
  if (!byEpoch[epoch]) byEpoch[epoch] = {};
  byEpoch[epoch][vin] = true;
  if (!priceByEpoch[epoch]) priceByEpoch[epoch] = {};
  const p = num(row && row.Price);
  if (p != null) priceByEpoch[epoch][vin] = p;
  if (vinFirst[vin] == null || epoch < vinFirst[vin]) vinFirst[vin] = epoch;
  if (vinLast[vin] == null || epoch >= vinLast[vin]) { vinLast[vin] = epoch; vinLastRow[vin] = row; }
}

for (const r of historyRows) observe(String(r.VIN), toEpoch(r['Snapshot Time']), r);
// Overlay today's snapshot so metrics are correct even if the History read lags one run.
for (const r of currentRows) observe(String(r.VIN), currentEpoch, r);

// Current inventory = today's VINs.
const currentSet = {};
const currentByVin = {};
for (const r of currentRows) { currentSet[String(r.VIN)] = true; currentByVin[String(r.VIN)] = r; }

// Previous snapshot = latest distinct epoch strictly before today's snapshot.
const epochs = Object.keys(byEpoch).map(Number).sort((a, b) => a - b);
let previous = null;
for (const e of epochs) { if (currentEpoch == null || e < currentEpoch) previous = e; }
const prevSet = previous != null ? byEpoch[previous] : {};

const currentVins = Object.keys(currentSet);
const newVins = currentVins.filter(v => !prevSet[v]);
const goneVins = previous != null ? Object.keys(prevSet).filter(v => !currentSet[v]) : [];

const nowEpoch = currentEpoch != null ? currentEpoch : Date.now();
const totalInInventory = currentVins.length;

// ----- New inventory (gross additions) by window -----
const firstAll = Object.keys(vinFirst);
function newWithin(days) { return firstAll.filter(v => (nowEpoch - vinFirst[v]) <= days * DAY).length; }
const newLast7 = newWithin(7);
const newLast90 = newWithin(90);
const newLast365 = newWithin(365);

// ----- Sold / removed by window -----
const goneAll = Object.keys(vinLast).filter(v => !currentSet[v]);
function soldWithin(days) { return goneAll.filter(v => (nowEpoch - vinLast[v]) <= days * DAY).length; }
function soldBetween(d1, d2) { return goneAll.filter(v => { const age = nowEpoch - vinLast[v]; return age > d1 * DAY && age <= d2 * DAY; }).length; }
const soldLast7 = soldWithin(7);
const soldLast90 = soldWithin(90);
const soldLast365 = soldWithin(365);
const avgSoldPerWeek = round(soldLast365 / 52, 2);

// ----- Revenue (sum of last-known listing price of sold/removed cars) -----
function soldPrice(v) { const row = vinLastRow[v] || {}; const p = num(row.Price); return p == null ? 0 : p; }
// Revenue for cars sold since the last run ("today's" revenue).
const revenuePerDay = sum(goneVins.map(soldPrice));

// Avg days a sold car stayed available.
let totalDays = 0, cnt = 0;
for (const v of goneAll) { const d = (vinLast[v] - vinFirst[v]) / DAY; if (isFinite(d) && d >= 0) { totalDays += d; cnt++; } }
const avgDaysAvailable = cnt ? round(totalDays / cnt, 1) : 0;

// ----- Inventory that existed at a given moment -----
function invAtEpoch(e) { let c = 0; for (const v of firstAll) { if (vinFirst[v] <= e && vinLast[v] >= e) c++; } return c; }

// ----- Sell-through rate = sold / (inventory at window start + additions in window) -----
function sellThrough(days) { const start = nowEpoch - days * DAY; const denom = invAtEpoch(start) + newWithin(days); return pct(soldWithin(days), denom); }
const sellThrough7 = sellThrough(7);
const sellThrough90 = sellThrough(90);
const sellThrough365 = sellThrough(365);

// ----- Weeks of supply = current inventory / avg weekly sales -----
const weeksOfSupply = avgSoldPerWeek ? round(totalInInventory / avgSoldPerWeek, 1) : '';

// ----- Aging of current inventory -----
const currentAges = currentVins.map(v => (nowEpoch - vinFirst[v]) / DAY);
const medianDaysOnLot = round(median(currentAges), 1);
function agedOver(d) { return currentAges.filter(a => a > d).length; }
const pctAged30 = pct(agedOver(30), totalInInventory);
const pctAged60 = pct(agedOver(60), totalInInventory);
const pctAged90 = pct(agedOver(90), totalInInventory);

// ----- Pricing -----
const currentPrices = currentRows.map(r => num(r.Price)).filter(x => x != null);
const avgPrice = currentPrices.length ? round(sum(currentPrices) / currentPrices.length, 0) : 0;
const medianPrice = currentPrices.length ? round(median(currentPrices), 0) : 0;

// ----- Per-trim stats -----
const byTrim = {};
function ensureTrim(t) { if (!byTrim[t]) byTrim[t] = { invCount: 0, priceSum: 0, priceN: 0, soldCount: 0, daysSum: 0, daysN: 0 }; return byTrim[t]; }
for (const r of currentRows) { const o = ensureTrim(trimOf(r.Model)); o.invCount++; const p = num(r.Price); if (p != null) { o.priceSum += p; o.priceN++; } }
for (const v of goneAll) { const row = vinLastRow[v] || {}; const o = ensureTrim(trimOf(row.Model)); o.soldCount++; const d = (vinLast[v] - vinFirst[v]) / DAY; if (isFinite(d) && d >= 0) { o.daysSum += d; o.daysN++; } }
function trimAvgPrice(t) { const o = byTrim[t]; return o && o.priceN ? round(o.priceSum / o.priceN, 0) : 0; }
function trimInvShare(t) { const o = byTrim[t]; return o ? pct(o.invCount, totalInInventory) : 0; }

// ----- Model-year mix (current inventory) -----
const myCount = {};
for (const r of currentRows) { const y = String(r['Model Year'] || '').trim() || 'Unknown'; myCount[y] = (myCount[y] || 0) + 1; }
const invShareMY2025 = pct(myCount['2025'] || 0, totalInInventory);
const invShareMY2026 = pct(myCount['2026'] || 0, totalInInventory);

// ----- Price cuts since previous snapshot -----
const curPrice = priceByEpoch[currentEpoch] || {};
const prevPrice = previous != null ? (priceByEpoch[previous] || {}) : {};
const priceCuts = [];
for (const v of Object.keys(curPrice)) { if (prevPrice[v] != null) { const diff = curPrice[v] - prevPrice[v]; if (diff < 0) priceCuts.push({ vin: v, oldP: prevPrice[v], newP: curPrice[v], cut: -diff }); } }
priceCuts.sort((a, b) => b.cut - a.cut);
const priceCutsCount = priceCuts.length;
const avgPriceCut = priceCutsCount ? round(sum(priceCuts.map(p => p.cut)) / priceCutsCount, 0) : 0;

// ----- Regional breakdown -----
const byState = {};
function ensureState(s) { if (!byState[s]) byState[s] = { inv: 0, sold90: 0 }; return byState[s]; }
for (const r of currentRows) { ensureState(String(r.State || '').trim() || 'Unknown').inv++; }
for (const v of goneAll) { if ((nowEpoch - vinLast[v]) <= 90 * DAY) { const row = vinLastRow[v] || {}; ensureState(String(row.State || '').trim() || 'Unknown').sold90++; } }

// ----- Trend (WoW / MoM) -----
const inv7 = invAtEpoch(nowEpoch - 7 * DAY);
const inv30 = invAtEpoch(nowEpoch - 30 * DAY);
const invWoW = inv7 ? pct(totalInInventory - inv7, inv7) : 0;
const invMoM = inv30 ? pct(totalInInventory - inv30, inv30) : 0;
const soldPrev7 = soldBetween(7, 14);
const salesWoW = soldPrev7 ? pct(soldLast7 - soldPrev7, soldPrev7) : 0;

// ----- Supply pipeline -----
const inTransitCount = currentRows.filter(r => isTrue(r['In Transit'])).length;
const atStudioCount = currentRows.filter(r => isTrue(r['At Studio'])).length;
const transitStudioRatio = atStudioCount ? round(inTransitCount / atStudioCount, 2) : '';

// ===== Build email body =====
const dateLabel = currentSnapshotTime.slice(0, 10);
let html = '';
html += '<h2>Lucid Inventory Daily Summary</h2>';
html += '<p>Snapshot: ' + esc(currentSnapshotTime) + '</p>';

html += '<h3>Headline</h3><ul>';
html += '<li>Total in inventory: ' + totalInInventory + '</li>';
html += '<li>New since last run: ' + newVins.length + '</li>';
html += '<li>Gone since last run (likely sold/removed): ' + goneVins.length + '</li>';
html += '<li>Weeks of supply: ' + weeksOfSupply + '</li>';
html += '</ul>';

html += '<h3>New inventory added</h3><ul>';
html += '<li>Past week: ' + newLast7 + '</li><li>Past quarter: ' + newLast90 + '</li><li>Past year: ' + newLast365 + '</li>';
html += '</ul>';

html += '<h3>Cars sold / removed</h3><ul>';
html += '<li>Past week: ' + soldLast7 + '</li><li>Past quarter: ' + soldLast90 + '</li><li>Past year: ' + soldLast365 + '</li>';
html += '<li>Avg sold per week (last 12 months): ' + avgSoldPerWeek + '</li>';
html += '<li>Avg days a car stays available: ' + avgDaysAvailable + '</li>';
html += '</ul>';

html += '<h3>Revenue (sold / removed cars)</h3><ul>';
html += '<li>Per day (sold since last run): ' + money(revenuePerDay) + '</li>';
html += '</ul>';

html += '<h3>Sell-through rate</h3><ul>';
html += '<li>Past week: ' + sellThrough7 + '%</li><li>Past quarter: ' + sellThrough90 + '%</li><li>Past year: ' + sellThrough365 + '%</li>';
html += '</ul>';

html += '<h3>Inventory aging (current stock)</h3><ul>';
html += '<li>Median days on lot: ' + medianDaysOnLot + '</li>';
html += '<li>Aged over 30 days: ' + pctAged30 + '%</li><li>Aged over 60 days: ' + pctAged60 + '%</li><li>Aged over 90 days: ' + pctAged90 + '%</li>';
html += '</ul>';

html += '<h3>Pricing</h3><ul>';
html += '<li>Average listing price: ' + money(avgPrice) + '</li><li>Median listing price: ' + money(medianPrice) + '</li>';
html += '<li>Price cuts since last run: ' + priceCutsCount + (priceCutsCount ? ' (avg ' + money(avgPriceCut) + ')' : '') + '</li>';
html += '</ul>';

html += '<h3>Trend</h3><ul>';
html += '<li>Inventory WoW: ' + invWoW + '%</li><li>Inventory MoM: ' + invMoM + '%</li><li>Sales WoW: ' + salesWoW + '%</li>';
html += '<li>In transit: ' + inTransitCount + ' | At studio: ' + atStudioCount + ' | Ratio: ' + transitStudioRatio + '</li>';
html += '</ul>';

// By-trim table.
html += '<h3>By trim</h3>';
let trimHtml = '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Trim</th><th>In inventory</th><th>Inv share</th><th>Avg price</th><th>Sold (all-time)</th><th>Avg days on lot</th></tr>';
const trimKeys = Object.keys(byTrim).sort((a, b) => byTrim[b].invCount - byTrim[a].invCount);
for (const t of trimKeys) { const o = byTrim[t]; const avgDays = o.daysN ? round(o.daysSum / o.daysN, 1) : ''; trimHtml += '<tr><td>' + esc(t) + '</td><td>' + o.invCount + '</td><td>' + pct(o.invCount, totalInInventory) + '%</td><td>' + money(o.priceN ? round(o.priceSum / o.priceN, 0) : '') + '</td><td>' + o.soldCount + '</td><td>' + avgDays + '</td></tr>'; }
trimHtml += '</table>';
html += trimHtml;

// Fastest / slowest moving trim.
const withDays = Object.keys(byTrim).filter(t => byTrim[t].daysN).map(t => ({ t: t, d: byTrim[t].daysSum / byTrim[t].daysN })).sort((a, b) => a.d - b.d);
if (withDays.length) { html += '<p>Fastest-moving trim: ' + esc(withDays[0].t) + ' (' + round(withDays[0].d, 1) + ' days). Slowest: ' + esc(withDays[withDays.length - 1].t) + ' (' + round(withDays[withDays.length - 1].d, 1) + ' days).</p>'; }

// Model-year mix.
html += '<h3>Model-year mix (current)</h3><ul>';
const myKeys = Object.keys(myCount).sort();
for (const y of myKeys) html += '<li>' + esc(y) + ': ' + myCount[y] + ' (' + pct(myCount[y], totalInInventory) + '%)</li>';
html += '</ul>';

// Regional table.
html += '<h3>By state</h3>';
let stateHtml = '<table border="1" cellpadding="4" cellspacing="0"><tr><th>State</th><th>In inventory</th><th>Sold last 90d</th></tr>';
const stKeys = Object.keys(byState).sort((a, b) => byState[b].inv - byState[a].inv);
for (const s of stKeys) { const o = byState[s]; stateHtml += '<tr><td>' + esc(s) + '</td><td>' + o.inv + '</td><td>' + o.sold90 + '</td></tr>'; }
stateHtml += '</table>';
html += stateHtml;

// Price cuts table.
html += '<h3>Price cuts since last run (' + priceCutsCount + ')</h3>';
if (priceCutsCount) {
  let cutHtml = '<table border="1" cellpadding="4" cellspacing="0"><tr><th>VIN</th><th>Model</th><th>Old price</th><th>New price</th><th>Cut</th></tr>';
  for (const p of priceCuts) { const row = currentByVin[p.vin] || {}; cutHtml += '<tr><td>' + esc(p.vin) + '</td><td>' + esc(row.Model) + '</td><td>' + money(p.oldP) + '</td><td>' + money(p.newP) + '</td><td>' + money(p.cut) + '</td></tr>'; }
  cutHtml += '</table>';
  html += cutHtml;
} else { html += '<p>None.</p>'; }

// New / gone vehicle tables.
function rowHtml(r) { return '<tr><td>' + esc(r.VIN) + '</td><td>' + esc(r.Model) + '</td><td>' + esc(r.Color) + '</td><td>' + money(num(r.Price)) + '</td><td>' + esc(r['Greater Area']) + '</td><td>' + esc(r.State) + '</td></tr>'; }
function table(vins, source) { if (!vins.length) return '<p>None.</p>'; let h = '<table border="1" cellpadding="4" cellspacing="0"><tr><th>VIN</th><th>Model</th><th>Color</th><th>Price</th><th>Area</th><th>State</th></tr>'; for (const v of vins) h += rowHtml(source[v] || { VIN: v }); h += '</table>'; return h; }
html += '<h3>New vehicles (' + newVins.length + ')</h3>' + table(newVins, currentByVin);
html += '<h3>Gone vehicles (' + goneVins.length + ')</h3>' + table(goneVins, vinLastRow);

if (!previous) html += '<p><em>Windowed and trend metrics are limited by how much history has accumulated; they become fully meaningful once the tracker has run for the corresponding period.</em></p>';

const subject = 'Lucid Inventory ' + dateLabel + ' - ' + newVins.length + ' new, ' + goneVins.length + ' gone';

return [{
  json: {
    'Snapshot Time': currentSnapshotTime,
    'Total In Inventory': totalInInventory,
    'New Vehicles': newVins.length,
    'Disappeared Vehicles': goneVins.length,
    'New Last 7 Days': newLast7,
    'New Last 90 Days': newLast90,
    'New Last 365 Days': newLast365,
    'Sold Last 7 Days': soldLast7,
    'Sold Last 90 Days': soldLast90,
    'Sold Last 365 Days': soldLast365,
    'Revenue Per Day': revenuePerDay,
    'Avg Sold Per Week (1yr)': avgSoldPerWeek,
    'Avg Days Available': avgDaysAvailable,
    'Sell-Through 7d %': sellThrough7,
    'Sell-Through 90d %': sellThrough90,
    'Sell-Through 365d %': sellThrough365,
    'Weeks Of Supply': weeksOfSupply,
    'Median Days On Lot': medianDaysOnLot,
    'Pct Aged 30+': pctAged30,
    'Pct Aged 60+': pctAged60,
    'Pct Aged 90+': pctAged90,
    'Avg Price': avgPrice,
    'Median Price': medianPrice,
    'Avg Price Pure': trimAvgPrice('Pure'),
    'Avg Price Touring': trimAvgPrice('Touring'),
    'Avg Price GT': trimAvgPrice('Grand Touring'),
    'Inv Share Pure %': trimInvShare('Pure'),
    'Inv Share Touring %': trimInvShare('Touring'),
    'Inv Share GT %': trimInvShare('Grand Touring'),
    'Inv Share MY2025 %': invShareMY2025,
    'Inv Share MY2026 %': invShareMY2026,
    'Price Cuts': priceCutsCount,
    'Avg Price Cut': avgPriceCut,
    'Inv WoW %': invWoW,
    'Inv MoM %': invMoM,
    'Sales WoW %': salesWoW,
    'In Transit Count': inTransitCount,
    'At Studio Count': atStudioCount,
    'In Transit/Studio Ratio': transitStudioRatio,
    emailSubject: subject,
    emailHtml: html,
  },
}];
